  'No resources found.': { fr: 'Aucune ressource trouvée.', de: 'Keine Ressourcen gefunden.', es: 'No se encontraron recursos.', ja: '資料が見つかりません。', zh: '未找到资源。' },
  'No safety letter has asked you to confirm you have read it.': { fr: 'Aucune lettre de sécurité ne vous a demandé de confirmer sa lecture.', de: 'Kein Sicherheitsbrief hat Sie um eine Lesebestätigung gebeten.', es: 'Ninguna carta de seguridad le ha pedido confirmar su lectura.', ja: '確認を求められている安全性レターはありません。', zh: '没有需要您确认已阅读的安全信函。' },
  'No submissions match your search.': { fr: 'Aucune demande ne correspond à votre recherche.', de: 'Keine Anfragen zu Ihrer Suche.', es: 'Ninguna solicitud coincide con su búsqueda.', ja: '検索に一致する依頼はありません。', zh: '没有符合搜索条件的提交。' },
